bool has_pair(const vector<long long>& a, long long target) {
    int n = a.size();

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i] + a[j] == target) {
                return true;
            }
        }
    }

    return false;
}

