#include <bits/stdc++.h>
using namespace std;

long long brute(const vector<long long>& a) {
    long long best = LLONG_MIN;
    for (int l = 0; l < (int)a.size(); l++) {
        long long sum = 0;
        for (int r = l; r < (int)a.size(); r++) {
            sum += a[r];
            best = max(best, sum);
        }
    }
    return best;
}

long long candidate(const vector<long long>& a) {
    long long best = LLONG_MIN;
    long long sum = 0;
    for (long long x : a) {
        sum = max(x, sum + x);
        best = max(best, sum);
    }
    return best;
}

